 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width colored rows are the horizontal version of the pattern.
    full_rows = {r: row[0] for r, row in enumerate(grid)
                 if row[0] != 0 and all(v == row[0] for v in row)}
    if full_rows:
        period = len(full_rows)
        by_phase = {r % period: color for r, color in full_rows.items()}
        return [[by_phase[r % period]] * w for r in range(h)]

    # Otherwise the colored diagonal bands encode one color per phase. Choose
    # the diagonal orientation that groups the most cells into the fewest
    # straight bands: c-r for down-right bands, c+r for down-left bands.
    bands = []
    for intercept_fn in (lambda r, c: c - r, lambda r, c: c + r):
        tracks = {}
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    key = intercept_fn(r, c)
                    if key in tracks and tracks[key] != color:
                        tracks[key] = None
                    else:
                        tracks[key] = color
        bands.append(tracks)

    # The correct orientation has the fewest distinct diagonals; ties favor
    # c-r, which is immaterial for perfectly symmetric patterns.
    tracks = min(bands, key=len)
    period = len(tracks)
    phase_color = {k % period: color for k, color in tracks.items()}
    use_sum = len(bands[1]) < len(bands[0])
    fn = (lambda r, c: c + r) if use_sum else (lambda r, c: c - r)
    return [[phase_color[fn(r, c) % period] for c in range(w)]
            for r in range(h)]
