    h, w = len(grid), len(grid[0])
    # Determine diagonal orientation by the streaks of equal-colored cells.
    candidates = []
    for sign in (-1, 1):  # intercept = c + sign*r
        tracks = {}
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    k = c + sign*r
                    tracks.setdefault(k, []).append(color)
        candidates.append((sum(len(v) for v in tracks.values()), tracks, sign))
    _, tracks, sign = max(candidates, key=lambda x: len(x[1]))
    # The color cycle is a five-diagonal motif; the source marks selected
    # phases and unmarked phases continue the closest prevailing color.
    period = 5
    phase_votes = {}
    for k, vals in tracks.items():
        p = k % period
        for color in vals:
            phase_votes.setdefault(p, []).append(color)
    phase = {}
    for p, vals in phase_votes.items():
        phase[p] = max(set(vals), key=vals.count)
    # Missing phase is the repeated/majority color; if tied, extend the
    # preceding phase around the cycle.
    if phase:
        fallback = max(set(c for vals in phase_votes.values() for c in vals),
                      key=lambda color: sum(vals.count(color) for vals in phase_votes.values()))
        for p in range(period):
            if p not in phase:
                phase[p] = fallback
    return [[phase[(c + sign*r) % period] for c in range(w)]
            for r in range(h)]
